/**
 * Returns the error correction block layout for a version and EC level.
 *
 * @param version - QR version (1-40)
 * @param ecLevel - Error correction level ('L' | 'M' | 'Q' | 'H')
 * @returns Block layout (groups and EC codewords per block)
 * @throws {RangeError} If version is outside 1-40 or the EC level is invalid
 */
export function getECBlocks(version: number, ecLevel: ECLevel): ECBlockInfo {
  const table = EC_BLOCKS[ecLevel as ECLevel];
  if (!table || !Number.isInteger(version) || version < 1 || version > 40) {
    throw new RangeError(
      `getECBlocks: invalid version (${version}) or EC level (${ecLevel})`,
    );
  }
  return table[version - 1]!;
}

/**
 * Total data codewords (capacity) for a version and EC level.
 *
 * @param version - QR version (1-40)
 * @param ecLevel - Error correction level ('L' | 'M' | 'Q' | 'H')
 * @returns Number of data codewords
 * @throws {RangeError} If version is outside 1-40 or the EC level is invalid
 */
export function getDataCodewords(version: number, ecLevel: ECLevel): number {
  const info = getECBlocks(version, ecLevel);
  return (
    info.numBlocksGroup1 * info.dataCodewordsGroup1 +
    info.numBlocksGroup2 * info.dataCodewordsGroup2
  );
}
